--
-- Table structure for table `ap_produk_bahan_baku`
--

CREATE TABLE `ap_produk_bahan_baku` (
  `id_produk` varchar(20) NOT NULL,
  `sku` varchar(20) NOT NULL,
  `qty` float NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci ROW_FORMAT=COMPACT;

-- --------------------------------------------------------

--
-- Table structure for table `ap_produk_discount_rules`
--

CREATE TABLE `ap_produk_discount_rules` (
  `id` int(255) NOT NULL,
  `id_produk` varchar(30) NOT NULL,
  `discount` int(15) NOT NULL,
  `qty` int(10) NOT NULL,
  `date_start` date NOT NULL,
  `date_end` date NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci ROW_FORMAT=COMPACT;

